def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    prev_bids = []
    dangerous_prev = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))
                if float(opp.get('water_requirement', WATER_REQ)) >= WATER_REQ:
                    dangerous_prev.append(float(bid))

    if not alive_opponents:
        if hp <= 2 or no_water_days >= 1:
            return float(min(budget, 40.0))
        return float(min(budget, 18.0))

    scarcity = 1.0 - ((supply - 15.0) / 10.0)
    if scarcity < 0.0:
        scarcity = 0.0
    if scarcity > 1.0:
        scarcity = 1.0

    high_pressure = max(prev_bids) if prev_bids else 0.0
    core_pressure = max(dangerous_prev) if dangerous_prev else high_pressure

    base = 26.0 + 18.0 * scarcity

    if core_pressure >= 110.0:
        target = 34.0 + 10.0 * scarcity
    elif core_pressure >= 80.0:
        target = max(base, 52.0 + 8.0 * scarcity)
    elif core_pressure >= 50.0:
        target = max(base, core_pressure + 3.0)
    elif core_pressure > 0.0:
        target = max(base, core_pressure + 2.0)
    else:
        target = base

    if supply <= 16.0:
        target += 10.0
    elif supply >= 23.0:
        target -= 6.0

    if hp <= 2:
        target = max(target, 66.0)
    elif hp <= 4:
        target = max(target, 54.0)

    if no_water_days >= 2:
        target = max(target, 69.0)
    elif no_water_days >= 1:
        target = max(target, 58.0)

    if day >= 8 and hp < 7:
        target += 6.0

    if budget < 80.0:
        target = min(target, budget * 0.72)
    elif budget < 160.0:
        target = min(target, budget * 0.58)

    if target < 0.0:
        target = 0.0

    return float(min(budget, round(target, 2)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']

    # Alive opponents
    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append(o)

    # If alone, bid enough but not wasteful
    if not alive_opps:
        return min(my_status['budget'], DAILY_SALARY * 0.4)

    # Read yesterday bids from previous_trace only
    prev_bids = []
    for o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    # Estimate how many winners are likely: with supply in [15,25] and requirement 9,
    # at most 2 players can be fully satisfied; competition tends to be for the top 1-2.
    # Use this to decide whether to match the aggression.
    try:
        supply_int = int(supply)
    except Exception:
        supply_int = int(float(supply))

    # Target bid logic: if others were aggressive yesterday, we slightly undercut to win
    # while preserving budget.
    aggressive_threshold = DAILY_SALARY * 0.85  # 76.5

    hp = my_status.get('hp', 0)
    budget = my_status.get('budget', 0)
    no_water_days = my_status.get('no_water_days', 0)

    # Base bid depending on our urgency
    if hp <= 2 or no_water_days >= 2:
        urgency_mult = 0.95
    elif hp <= 4 or no_water_days >= 1:
        urgency_mult = 0.75
    else:
        urgency_mult = 0.6

    # If yesterday's highest bid was high, we bid near it but not equal.
    if highest_prev_bid >= aggressive_threshold:
        # Undercut by a small margin; also cap by urgency.
        target = highest_prev_bid - 3.0
        # Ensure still competitive
        floor = DAILY_SALARY * 0.55
        target = max(target, floor)
    else:
        # When others were moderate, bid around mid
        target = max(DAILY_SALARY * 0.5, highest_prev_bid * 0.85 + 5.0)

    # Supply adjustment: lower supply -> higher competition
    if supply_int <= 17:
        target *= 1.10
    elif supply_int >= 23:
        target *= 0.95

    # Final cap by budget
    bid = min(budget, target * urgency_mult)

    # If budget is very small, still bid something rational
    if bid < 0:
        bid = 0
    if bid == 0 and budget > 0:
        bid = min(budget, 1.0)

    return float(bid)

